javascript:function getPageHtml(dom) {
  var iframeContent="";  var frameContent="";  const ifrs = dom.getElementsByTagName("iframe");
  const frs = dom.getElementsByTagName("frame");
  for (var i = 0; i < ifrs.length; i++) {
     try {
         iframeContent += getPageHtml(ifrs[i].contentDocument.body.parentElement);
     } catch (error) { }
  }
  for (var i = 0; i < frs.length; i++) {
     try {
         frameContent += getPageHtml(frs[i].contentDocument.body.parentElement);
     } catch (error) { }
  }
  if (dom === document) {
    return (
      document.getElementsByTagName("html")[0].innerHTML + iframeContent + frameContent
    );
  }
  return dom.innerHTML + iframeContent + frameContent;
}

